package com.lore.zzal.attendance;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.awt.image.BufferedImage;import java.io.*;import javax.imageio.ImageIO;import com.lore.common.s3.S3Storage;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class CustomReviewSequenceTest{
 static final ObjectMapper J=new ObjectMapper();static final String PREFIX="images/zzal/custom/00000000-0000-0000-0000-000000000001";@TempDir Path dir;
 ObjectNode anchors(List<String> slots){var n=J.createObjectNode();n.put("version","1");n.putObject("canvas").put("w",16).put("h",16);n.put("K",12);n.put("Hw",6);n.put("privatePlan","NEVER_RETURN");var poses=n.putObject("poses");for(String slot:slots){var p=poses.putObject(slot);p.putObject("bbox").put("x",1).put("y",1).put("w",14).put("h",14);p.putObject("head_top").put("x",8).put("y",1);for(String field:List.of("head_side","hand_front","feet")){var a=p.putObject(field).put("y",14).put("left_x",2).put("right_x",14);if(field.equals("feet"))a.put("center_x",8);}}return n;}
 ObjectNode manifest(){var m=J.createObjectNode();m.put("version",CustomReviewSequence.VERSION);m.put("setId",PREFIX.substring(PREFIX.lastIndexOf('/')+1));m.put("baseRound",2);m.put("baseAnchorsKey","images/zzal/pets/9/basic/2/anchors.json");m.put("customAnchorsKey",PREFIX+"/anchors.json");m.put("K",12);m.put("Hw",6);m.put("alphaBoundsThreshold",0);var fs=m.putArray("frames");for(int i=0;i<32;i++){boolean basic=i<16;int order=i%16/2+1;String slot=(basic?CustomReviewSequence.BASIC:CustomGridPrompt.SLOTS).get(order-1);var f=fs.addObject();f.put("index",i).put("group",basic?"BASIC":"CUSTOM").put("motionOrder",order).put("frameIndex",i%2).put("slot",slot).put("imageKey",PREFIX+String.format("/review/sequence-v1/frame-%02d.png",i+1)).put("sourceImageKey",basic?"images/zzal/pets/9/basic/2/"+slot+".webp":PREFIX+"/"+slot+".webp").put("sha256","a".repeat(64)).put("sourceSha256","b".repeat(64)).put("rgbaSHA256","c".repeat(64)).put("durationMs",450).put("width",16).put("height",16);f.putArray("alphaBounds").add(1).add(1).add(15).add(15);}return m;}
 CustomReviewSequence.Sequence validate(JsonNode m)throws Exception{return CustomReviewSequence.validate(m,9,2,PREFIX,anchors(CustomReviewSequence.BASIC),anchors(CustomGridPrompt.SLOTS),Map.of());}
 @Test void exact32MappingAndOnlyNumericAnchorProjection()throws Exception{var s=validate(manifest());assertEquals(32,s.frames().size());assertEquals("startle",s.frames().get(28).slot());assertEquals("wake_up",s.frames().get(30).slot());assertFalse(s.baseAnchors().has("privatePlan"));assertEquals(Set.of("version","canvas","K","Hw","poses"),new HashSet<>(new ObjectMapper().convertValue(s.customAnchors(),Map.class).keySet()));}
 @Test void rejectsFabricatedDurationMappingAndForeignOwner()throws Exception{for(String field:List.of("durationMs","frameIndex")){var m=manifest();((ObjectNode)m.path("frames").get(0)).put(field,field.equals("durationMs")?0:1);assertThrows(IllegalArgumentException.class,()->validate(m));}var m=manifest();((ObjectNode)m.path("frames").get(0)).put("sourceImageKey","images/zzal/pets/10/basic/2/base.webp");assertThrows(IllegalArgumentException.class,()->validate(m));}
 @Test void rejectsMissingRequiredAnchorAndDbSourceHashMismatch(){var a=anchors(CustomReviewSequence.BASIC);((ObjectNode)a.path("poses").path("base").path("feet")).remove("center_x");assertThrows(IllegalArgumentException.class,()->CustomReviewSequence.validate(manifest(),9,2,PREFIX,a,anchors(CustomGridPrompt.SLOTS),Map.of()));assertThrows(IllegalArgumentException.class,()->CustomReviewSequence.validate(manifest(),9,2,PREFIX,anchors(CustomReviewSequence.BASIC),anchors(CustomGridPrompt.SLOTS),Map.of(PREFIX+"/eat_rice.webp","d".repeat(64))));}
 @Test void pngDigestIncludesTransparentAndSemitransparentRgb()throws Exception{var image=new BufferedImage(16,16,BufferedImage.TYPE_INT_ARGB);image.setRGB(0,0,0x00123456);image.setRGB(2,3,0x80402010);var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);var digest=java.security.MessageDigest.getInstance("SHA-256");for(int y=0;y<16;y++)for(int x=0;x<16;x++){int p=image.getRGB(x,y);digest.update((byte)(p>>>16));digest.update((byte)(p>>>8));digest.update((byte)p);digest.update((byte)(p>>>24));}var f=new CustomReviewSequence.Frame(0,"BASIC",1,"base",0,"x",CustomReviewSequence.hash(bytes.toByteArray()),"s","b".repeat(64),450,16,16,List.of(2,3,3,4),HexFormat.of().formatHex(digest.digest()));CustomReviewSequence.verifyPng(f,bytes.toByteArray());byte[] broken=bytes.toByteArray();broken[broken.length-1]^=1;assertThrows(IllegalArgumentException.class,()->CustomReviewSequence.verifyPng(f,broken));}
 @Test void missingLegacyBasicIsOptionalAndNeverRunsExporter()throws Exception{String frozen="{\"memory\":{\"petId\":9}}";var req=mock(CustomGenerationRequest.class);when(req.requestId()).thenReturn(UUID.fromString(PREFIX.substring(PREFIX.lastIndexOf('/')+1)));when(req.frozenSnapshot()).thenReturn(frozen);var profile=mock(CustomPostprocessProfile.class);when(profile.baseReferenceRound()).thenReturn(2);when(profile.anchorsKey()).thenReturn("images/zzal/pets/9/basic/2/anchors.json");var storage=mock(S3Storage.class);doThrow(new IllegalStateException("missing historical asset")).when(storage).download(anyString(),any(Path.class));var status=CustomReviewSequence.create(storage,req,profile,dir,"MUST_NOT_RUN");assertEquals("INCOMPLETE",status.path("status").asText());assertEquals("BASIC_ASSET_UNAVAILABLE",status.path("reasonCode").asText());verify(storage,never()).upload(anyString(),any(Path.class),anyString());}
 @Test void cancellationRestoresInterruptInsteadOfPublishingOptionalSuccess()throws Exception{var req=mock(CustomGenerationRequest.class);when(req.requestId()).thenReturn(UUID.randomUUID());when(req.frozenSnapshot()).thenReturn("{\"memory\":{\"petId\":9}}");var profile=mock(CustomPostprocessProfile.class);when(profile.baseReferenceRound()).thenReturn(2);when(profile.anchorsKey()).thenReturn("images/zzal/pets/9/basic/2/anchors.json");var storage=mock(S3Storage.class);doAnswer(i->{Thread.currentThread().interrupt();throw new IllegalStateException("cancel");}).when(storage).download(anyString(),any(Path.class));try{assertThrows(InterruptedException.class,()->CustomReviewSequence.create(storage,req,profile,dir,"MUST_NOT_RUN"));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
}
